      | c = Property $(2)$ of $\ast$
}}
{{eqn | r = a \ast \paren {\paren {e \ast c} \ast b}
      | c = Property $(2)$ of $\ast$
}}
{{eqn | r = a \ast \paren {e \ast \paren {b \ast \paren {e \ast c} } }
